/* ---------- 持久化 ---------- */
let films = load();
ensureFilmNumbers();   // 补全已录入人员但未分配编号的电影
patchSeedFilms();      // 用最新 seed 数据覆盖本地旧版电影字段（如信息纠错后同步到用户本地）
const state = {admin:false, newWatch:{film:null,date:'',people:[]}};
let ocrState = {people:[], date:'', film:''};
let viewY, viewM;   // 日历当前展示的年月

function load(){
  // 权威数据源：部署在 app.js 内的 seed（管理员集中维护，发布后所有访问者都应看到最新内容）。
  // localStorage 仅用于叠加用户在前端 UI 本地新建的影片（id 不在 seed 中的 'u'+时间戳 影片），
  // 不再以 localStorage 覆盖 seed 中已发布影片的观影者名单，避免老用户长期停留在旧的本地缓存数据。
  const s = seed();
  s.forEach(enrich);
  try{
    const raw = localStorage.getItem(STORAGE_KEY);
    if(raw){
      const data = JSON.parse(raw);
      if(data && Array.isArray(data.films)){
        const seedIds = new Set(s.map(f => f.id));
        data.films.forEach(lf => { if(!seedIds.has(lf.id)){ enrich(lf); s.push(lf); } });
      }
    }
  }catch(e){}
  try{ localStorage.setItem(STORAGE_KEY, JSON.stringify({films:s})); }catch(e){}
  return s;
}
function enrich(f){
  if(typeof f.poster !== 'string') f.poster = '';
  if(typeof f.synopsis !== 'string') f.synopsis = '';
  if(!Array.isArray(f.cast)) f.cast = CAST[baseOf(f.id)] || [];
}
function save(){
  try{ localStorage.setItem(STORAGE_KEY, JSON.stringify({films})); }catch(e){}
}

/* ---------- 点赞（公开轻互动，独立于观影档案存储，不被重新播种清空） ----------
   结构：{ counts:{[filmId]:累计赞}, today:{[当日日期_filmId]:今日已点} }
   限额：每部电影每日最多 +10。 */
const LIKES_KEY = 'filmlog_likes_v1';
const LIKE_DAILY_CAP = 10;
function loadLikes(){
  try{
    const raw = localStorage.getItem(LIKES_KEY);
    if(raw){ const d = JSON.parse(raw); return { counts: d.counts || {}, today: d.today || {} }; }
  }catch(e){}
  return { counts:{}, today:{} };
}
let likes = loadLikes();
function saveLikes(){
  try{ localStorage.setItem(LIKES_KEY, JSON.stringify(likes)); }catch(e){}
}
function likeKey(filmId){ return isoOf(new Date()) + '_' + filmId; }
function likeTodayCount(filmId){ return likes.today[likeKey(filmId)] || 0; }
function likeTotal(filmId){ return likes.counts[filmId] || 0; }
function canLike(filmId){ return likeTodayCount(filmId) < LIKE_DAILY_CAP; }
function addLike(filmId){
  if(!canLike(filmId)) return false;
  likes.counts[filmId] = (likes.counts[filmId] || 0) + 1;
  likes.today[likeKey(filmId)] = (likes.today[likeKey(filmId)] || 0) + 1;
  saveLikes();
  return true;
}
function onLike(filmId){
  const btn = document.getElementById('likeBtn');
  const cnt = document.getElementById('likeCount');
  const note = document.getElementById('likeNote');
  if(!canLike(filmId)){
    if(btn) btn.disabled = true;
    if(note) note.textContent = `今日已达上限（${LIKE_DAILY_CAP}）`;
    return;
  }
  addLike(filmId);
  if(cnt) cnt.textContent = likeTotal(filmId);
  if(!canLike(filmId)){
    if(btn) btn.disabled = true;
    if(note) note.textContent = `今日已达上限（${LIKE_DAILY_CAP}）`;
  }
}

/* 个人页观影记录：折叠/展开（点击 ··· 依次展开余下，每行三部） */
function toggleHistory(btn){
  const grid = btn.previousElementSibling;
  if(grid && grid.classList.contains('history-compact')){
    const open = grid.classList.toggle('expanded');
    btn.textContent = open ? '收起' : '···';
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
  }
}
/* 电影页：档案信息折叠（点击 ··· 展开运营数据） */
function toggleArchive(btn){
  const box = btn.nextElementSibling;
  if(box && box.classList.contains('archive-collapse')){
    const open = box.classList.toggle('expanded');
    btn.textContent = open ? '收起档案信息' : '··· 档案信息';
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
  }
}

/* ---------- 工具 ---------- */
function esc(s){
  return String(s ?? '').replace(/[&<>"']/g, m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
}
const MONTHS = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
function fmtDate(iso){
  if(!iso) return '—';
  const d = new Date(iso + 'T00:00:00');
  if(isNaN(d)) return esc(iso);
  return `${String(d.getDate()).padStart(2,'0')} ${MONTHS[d.getMonth()]} ${d.getFullYear()}`;
}
function fmtDateCN(iso){
  if(!iso) return '—';
  const d = new Date(iso + 'T00:00:00');
  if(isNaN(d)) return esc(iso);
  return `${d.getFullYear()} 年 ${d.getMonth()+1} 月 ${d.getDate()} 日`;
}
function isoOf(d){ return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }
/* 编号：id 可以是纯数字 "30" 或带后缀 "30-a"/"30-b"。
   基础编号（base）始终为数字，后缀仅用于同一电影在不同位置/时间的并列呈现，
   保证「同一部电影无论怎么调整时间都归在同一基础编号之下」，避免编号冲突。
   显示时统一去掉后缀的连字符，呈现为 "FILM 030" / "FILM 030A"。 */
function baseOf(id){ return parseInt(String(id).split('-')[0], 10) || 0; }
function isSuffixed(id){ return /^\d+-[a-z]+$/i.test(String(id)); }
function suffixOf(id){ const m = String(id).match(/-([a-z]+)$/i); return m ? m[1].toUpperCase() : ''; }
function no(id){
  const n = baseOf(id);
  const s = suffixOf(id);
  return 'FILM ' + String(n).padStart(3,'0') + s;
}
/* ---------- 用户别名（基础设定） ----------
   部分观影者对外使用真实名称。无论录入时写的是别名还是真实名，
   都按此表合并为对外名称统一展示。例如「晏秋」即「叶斯安德」，
   录入「晏秋」或「叶斯安德」都会合并为「叶斯安德」显示。
   后续有类似情况，直接在 ALIASES 中加一行即可。

   【归类经验：视觉识别变体】群接龙/截图里的昵称可能因字体或识别原因产生
   「形近字变体」，录入前先与已注册名比对字形。已知案例：
   「火冋火冋」(冋=jiōng) 常被写成/看成「火同火同」「火问火同」「火问火问」，
   凡遇到 火?火? 形态的名字一律归一为「火冋火冋」，不要新建用户。 */
const ALIASES = {
  '火同火同': '火冋火冋', '子矜': '子衿', '晏秋': '叶斯安德', '子裕': '子衿', '若涵': 'Esja', '🐰道长': '道长', '小鹰': '道长', '忧郁🐰': '🐰', '乱步': '海岛', '捡拎': '拎拎', '拎玲': '拎拎', 'glen': '林三', 'Thanos': '林三', '回溯性的断裂': '回溯性断裂', '断裂': '回溯性断裂', '17': '安静电影型17', 'ト': '卜', '明天的盐（又名😴）': '明天的盐', '林三01': '林三', 'Coconut🥥': 'Coconut', 'Josh_Z': 'Josh', '安静电影型17 简单来了': '安静电影型17', '安静电影型17 简单照镜子': '安静电影型17', '安静电影型17 安静库布里克': '安静电影型17', '复读bot17号': '安静电影型17', '火问火问': '火冋火冋', '火问火同': '火冋火冋', '火冏火冏': '火冋火冋', 'Alex': 'Alex_', 'coconut': 'Coconut', '兔子': '🐰', '朱': '番茄', '牛ノ＼': '番茄', '加西西红柿': '西西红柿🍅' };

/* ---------- 用户名变体自动归并规则 ----------
   规则：当「新出现的用户名」包含某个「已存在的用户名」时，若多出来的那一截
   只是噪声变体（仅增加了 数字 / 数字+号 / 括号注释 / 纯 emoji / 单个"的" / 已知后缀），
   则自动合并到已存在的干净基名，避免同一人被拆成多个账号。
   判定是"单向"的：只对新名（不在已知名集合里的）做探测，且只向已存在的干净名合并，
   因此绝不会把干净名反向并回带噪声的变体。
   多余部分若含字母/中文等"有意义"字符（如 shuyu 里的 shu、安静电影型17 里的 安静电影型），
   一律视为"拿不准"，不自动合并，交由人工判断。
   "X朋友"/"X的朋友" 明确判为不同人，不合并。 */
const VARIANT_NOISE_SUFFIX = new Set(['号','号','同学','酱','君','桑','bot','Bot','宝宝','佬']);
function _isVariantExtra(extra){
  if(extra === '') return false;
  if(/^[\d]+$/.test(extra)) return true;                          // 纯数字
  if(/^[\d]+(号|号)$/.test(extra)) return true;                   // 数字+号
  if(/^[（(][^（）()]{1,12}[)）]$/.test(extra)) return true;       // 括号注释
  if(extra === '的') return true;                                 // 单个"的"
  if(VARIANT_NOISE_SUFFIX.has(extra)) return true;               // 已知后缀
  if(/^[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE00}-\u{FE0F}\u{1F1E6}-\u{1F1FF}\u{2700}-\u{27BF}\u{2B00}-\u{2BFF}]+$/u.test(extra)) return true; // 纯 emoji
  return false;
}
let _KNOWN_NAMES = null;
function _knownNames(){
  if(_KNOWN_NAMES) return _KNOWN_NAMES;
  const s = new Set();
  (typeof films !== 'undefined' ? films : []).forEach(f => (f.watches||[]).forEach(w => (w.people||[]).forEach(p => s.add(p))));
  _KNOWN_NAMES = new Set([...s].map(p => ALIASES[p] || p));      // 解析为 canon 名集合
  return _KNOWN_NAMES;
}
function _variantMerge(name){
  const known = _knownNames();
  let best = null, bestLen = 0;
  for(const Y of known){
    if(!Y || Y === name) continue;
    const idx = name.indexOf(Y);
    if(idx < 0 || Y.length < 2) continue;                        // 基名过短易误命中，跳过
    const extra = name.slice(0, idx) + name.slice(idx + Y.length);
    if(_isVariantExtra(extra) && Y.length > bestLen){ best = Y; bestLen = Y.length; }
  }
  return best;
}
const canon = name => {
  if(name == null) return name;
  let n = ('' + name).trim();
  if(ALIASES[n]) n = ALIASES[n];
  if(!_knownNames().has(n)){                                      // 仅对「新出现」的名做变体探测
    const m = _variantMerge(n);
    if(m) n = m;
  }
  return n;
};

/* 中文名首字母（声母）轻量映射：覆盖档案中已出现的高频字，非字典级。
   未命中中文统一归到「#」组。英文名/数字直接取首字符。 */
const PINYIN_MAP = {
  '叶':'Y','李':'L','安':'A','王':'W','火':'H','三':'S','拎':'L','于':'Y','岩':'Y','宫':'G',
  '柳':'L','贾':'J','苏':'S','菲':'F','玛':'M','周':'Z','林':'L','张':'Z','陈':'C','刘':'L',
  '吴':'W','郑':'Z','何':'H','黄':'H','赵':'Z','孙':'S','徐':'X','马':'M','朱':'Z','胡':'H',
  '郭':'G','何':'H','高':'G','罗':'L','梁':'L','宋':'S','唐':'T','韩':'H','冯':'F','邓':'D',
  '曹':'C','彭':'P','曾':'Z','萧':'X','田':'T','董':'D','潘':'P','袁':'Y','蔡':'C','蒋':'J',
  '余':'Y','杜':'D','叶':'Y','程':'C','苏':'S','魏':'W','吕':'L','丁':'D','沈':'S','任':'R',
  '姚':'Y','卢':'L','傅':'F','钟':'Z','姜':'J','崔':'C','谭':'T','廖':'L','范':'F','汪':'W',
  '陆':'L','金':'J','石':'S','戴':'D','贾':'J','韦':'W','牛':'N','温':'W','盐':'Y','爱':'A',
  '我':'W','文':'W','之':'Z','子':'Z','阿':'A','困':'K','岛':'D','一':'Y','南':'N','还':'H',
  '夏':'X','悠':'Y','美':'M','是':'S','的':'D','啊':'A','让':'R','着':'Z','厨':'C','雪':'X',
  '乐':'L','耐':'N','安':'A','静':'J','君':'J','宝':'B','柏':'B','布':'B','蔷':'Q','微':'W',
  '末':'M','松':'S','松':'S','广':'G','永':'Y','工':'G','真':'Z','泽':'Z','瑞':'R','铃':'L',
  '明':'M','小':'X','尤':'Y','元':'Y','云':'Y','雨':'Y','蓝':'L','红':'H','绿':'L','白':'B'
};
function pinyinInitial(name){
  if(!name) return '#';
  const ch = String(name).trim()[0];
  const code = ch.charCodeAt(0);
  // 拉丁字母 A–Z
  if(code >= 65 && code <= 90) return ch;
  if(code >= 97 && code <= 122) return ch.toUpperCase();
  // 数字 / 符号 → #
  if(code < 0x4e00){ return '#'; }
  // 中文（CJK）：查映射表，未命中归 #
  return PINYIN_MAP[ch] || '#';
}
/* 全部已录入观影者（去重、归一化）：用于 Cinephile 名单页 */
function allWatchers(){
  const set = new Set();
  films.forEach(f => f.watches.forEach(w => w.people.forEach(p => {
    const n = canon(stripFunc(p));
    if(n) set.add(n);
  })));
  return [...set];
}
/* 按首字母分组（A–Z 在前，# 在最后），组内 localeCompare 排序 */
function groupWatchers(){
  const groups = {};
  allWatchers().forEach(n => {
    const k = pinyinInitial(n);
    (groups[k] = groups[k] || []).push(n);
  });
  const keys = Object.keys(groups).sort((a,b) => {
    if(a === '#') return 1;
    if(b === '#') return -1;
    return a.localeCompare(b);
  });
  keys.forEach(k => groups[k].sort((x,y) => x.localeCompare(y, 'zh')));
  return keys.map(k => ({ letter: k, names: groups[k] }));
}

