function admin(){
  const totalWatches = films.reduce((n,f)=> n + f.watches.length, 0);
  const recent = allFilms().slice(0,4);
  const html = `<main class="admin-main">
    <div class="eyebrow">ADMIN</div>
    <div class="admin-heading">管理后台</div>
    <div class="admin-sub">${films.length} 部电影 · ${totalWatches} 条观影记录</div>
    <div class="btn-row"><button class="btn primary" onclick="go('#/admin/new/1')">＋ 新增观影</button></div>
    <div class="divider"></div>
    <div class="eyebrow">最近记录</div>
    ${recent.map(f => `<div class="result" onclick="go('#/film/${f.id}')">
      <div class="film-no">${no(f.id)}</div>
      <div class="film-name">${esc(f.title)}</div>
      <div class="film-meta">${fmtDate(latestDate(f))} · ${f.watches.length} 次观影</div>
    </div>`).join('')}
  </main>`;
  return wrap(html, true);
}
function newStep(step){
  const n = state.newWatch;
  if(step === 1){
    const html = `<main class="admin-main">
      <div class="eyebrow">NEW WATCH</div>
      <div class="admin-step">01 / 04　电影</div>
      <div class="admin-heading">选择电影</div>
      <input id="filmSearch" class="field sans" placeholder="搜索已有电影" oninput="renderFilmChoices(this.value)">
      <div id="filmChoices" class="result-list">${filmChoices('')}</div>
      <div class="btn-row"><button class="btn ghost" onclick="go('#/admin')">取消</button></div>
    </main>`;
    return wrap(html, true);
  }
  if(step === 2){
    const f = n.film; if(!f) return go('#/admin/new/1');
    const html = `<main class="admin-main">
      <div class="eyebrow">NEW WATCH</div>
      <div class="admin-step">02 / 04　日期</div>
      <div class="admin-heading">观影日期</div>
      <div class="admin-sub">${esc(f.title)} · ${esc(f.original)}</div>
      <input id="watchDate" class="field date-input" type="date" value="${esc(n.date||'')}">
      <div class="btn-row">
        <button class="btn ghost" onclick="go('#/admin/new/1')">上一步</button>
        <button class="btn primary" onclick="saveDate()">下一步</button>
      </div>
    </main>`;
    return wrap(html, true);
  }
  if(step === 3){
    const html = `<main class="admin-main">
      <div class="eyebrow">NEW WATCH</div>
      <div class="admin-step">03 / 04　参与者</div>
      <div class="admin-heading">参与者</div>
      <div class="admin-sub">上传微信接龙或 AA 清单截图。V1 原型用示例名单模拟 AI 识别，后续接入视觉模型；确认后原始截图将被删除。</div>
      <label class="upload">
        <input type="file" accept="image/*" onchange="simulateOCR(this)">
        <span><strong>＋ 上传截图</strong><span class="upload-hint">点击选择图片</span></span>
      </label>
      <div id="ocrArea">${n.people.length ? adminPeopleEditor() : ''}</div>
    </main>`;
    return wrap(html, true);
  }
  if(step === 4){
    const f = n.film; if(!f) return go('#/admin/new/1');
    const html = `<main class="admin-main">
      <div class="eyebrow">NEW WATCH</div>
      <div class="admin-step">04 / 04　确认</div>
      <div class="admin-heading">确认观影记录</div>
      <div class="summary">
        <div class="summary-block">
          <div class="summary-label">电影</div>
          <div class="summary-value">${esc(f.title)}<div class="entry-original">${esc(f.original)}</div></div>
        </div>
        <div class="summary-block">
          <div class="summary-label">日期</div>
          <div class="summary-value">${fmtDate(n.date)}</div>
        </div>
        <div class="summary-block">
          <div class="summary-label">参与者 · ${n.people.length} 人</div>
          <div class="summary-value">${n.people.map(esc).join(' · ')}</div>
        </div>
      </div>
      <div class="btn-row">
        <button class="btn ghost" onclick="go('#/admin/new/3')">返回修改</button>
        <button class="btn primary" onclick="publishWatch()">确认并保存</button>
      </div>
    </main>`;
    return wrap(html, true);
  }
}
function filmChoices(q){
  const query = (q||'').toLowerCase();
  const list = films.filter(f => !query || f.title.toLowerCase().includes(query) || f.original.toLowerCase().includes(query));
  if(!list.length) return `<div class="empty">未找到已有电影</div>`;
  return list.map(f => {
    const full = f.watches.length >= 2;
    return `<div class="result" ${full?'':`onclick="selectFilm(${f.id})"`} style="${full?'opacity:.45;cursor:not-allowed':''}">
      <div class="film-no">${no(f.id)}</div>
      <div class="film-name">${esc(f.title)}</div>
      <div class="film-meta">${esc(f.year)} · ${esc(f.director)} · ${esc(f.rating)} · ${f.watches.length>=2?'已达两次观影上限':'可继续添加'}</div>
    </div>`;
  }).join('');
}
function renderFilmChoices(q){ const el=document.getElementById('filmChoices'); if(el) el.innerHTML=filmChoices(q); }
function selectFilm(id){
  const f = films.find(x => x.id === id);
  if(!f) return;
  if(f.watches.length >= 2){ alert('该电影已达两次观影上限（同一电影最多两次观影）。'); return; }
  state.newWatch = {film:f, date:'', people:[]};
  go('#/admin/new/2');
}
function saveDate(){
  const v = document.getElementById('watchDate') && document.getElementById('watchDate').value;
  if(!v){ alert('请选择观影日期'); return; }
  state.newWatch.date = v; go('#/admin/new/3');
}
function simulateOCR(input){
  if(!(input.files && input.files.length)) return;
  const demo = ['张三','Alex','MIKA','老王','小陈','小林'];
  state.newWatch.people = demo;
  renderAdminOCR();
}
function renderAdminOCR(){
  const area = document.getElementById('ocrArea');
  if(!area) return;
  area.innerHTML = `<div class="ocr">
    <div class="ocr-title">识别完成 · ${state.newWatch.people.length} 人（原型模拟）</div>
    ${adminPeopleEditor()}
    <div class="btn-row">
      <button class="btn ghost" onclick="adminClearOCR()">重新上传</button>
      <button class="btn primary" onclick="go('#/admin/new/4')">确认名单</button>
    </div>
  </div>`;
}
function adminClearOCR(){ state.newWatch.people=[]; const a=document.getElementById('ocrArea'); if(a) a.innerHTML=''; }
function adminPeopleEditor(){
  return state.newWatch.people.map((p,i)=>
    `<div class="person"><span>${esc(p)}</span><button class="remove" onclick="adminRemovePerson(${i})">×</button></div>`
  ).join('') + `<div class="add-person">
    <input id="newPerson" class="field" placeholder="手动添加参与者">
    <button class="btn" onclick="adminAddPerson()">添加</button>
  </div>`;
}
function adminRemovePerson(i){ state.newWatch.people.splice(i,1); renderAdminOCR(); }
function adminAddPerson(){
  const el=document.getElementById('newPerson'); const v=(el&&el.value||'').trim();
  if(!v) return; state.newWatch.people.push(v); el.value=''; renderAdminOCR();
}
function publishWatch(){
  const n = state.newWatch;
  if(!n.film || !n.date || !n.people.length){ alert('记录信息不完整'); return; }
  if(n.film.watches.length >= 2){ alert('该电影已达两次观影上限。'); return; }
  n.film.watches.push({date:n.date, people:[...n.people]});
  save();
  const f = n.film; const saved = {id:f.id, title:f.title, date:n.date, count:n.people.length};
  state.newWatch = {film:null, date:'', people:[]};
  document.getElementById('app').innerHTML = wrap(`<main class="admin-main success">
    <div class="ok">SAVED</div>
    <div class="success-title">${no(saved.id)}</div>
    <div class="success-date">${fmtDate(saved.date)} · ${saved.count} 人</div>
    <div class="divider"></div>
    <div class="success-title">${esc(saved.title)}</div>
    <div class="btn-row">
      <button class="btn primary" onclick="go('#/')">返回日历</button>
      <button class="btn ghost" onclick="go('#/admin/new/1')">继续添加观影</button>
    </div>
  </main>`, true);
}

/* ---------- 隐藏预览页（彩蛋：点击首页底部"档"字进入） ----------
   仅在 #/preview 路由下渲染；数据取自已加载的 films（实时同步主站）。
   不含任何导航入口，普通人不会误入。 */
function previewBadgeName(k){
  if(BADGE_DEFS[k] && BADGE_DEFS[k].name) return BADGE_DEFS[k].name;
  const km=/^king-(\d{4})-(\d{2})$/.exec(k); if(km) return Number(km[2])+'月观影帝';
  const jz=/^jz\+(\d+)$/.exec(k); if(jz) return '鸡爪+'+jz[1];
  const map={jzking:'鸡爪王',islandlove:'海岛之爱·周年见证',fullattend:'全勤强',comedian:'欢乐喜剧人',closet:'崆峒即深柜',hardwin:'精品男大',recorder:'观影记录员',snowking:'雪王的凝视',shareholder:'流光精神股东'};
  return map[k]||k;
}
function previewPage(){
  // 隐藏预览页：仅保留「谁和谁最常一起看（可交互）」弦图模块
  const inner = `<main class="preview">
    <div class="eyebrow">FILM LOG · 内部预览（彩蛋）</div>

    <section>
      <h2>谁和谁最常一起看（可交互）</h2>
      <div class="toolbar">
        <label>最少共看次数 <b id="cvThVal">3</b></label>
        <input type="range" id="cvTh" min="2" max="11" value="3">
        <button id="previewReset">重置</button>
        <span class="ts" id="previewGraphTs">生成中…</span>
      </div>
      <div class="graph-area">
        <svg id="previewGraph" viewBox="0 0 760 620" preserveAspectRatio="xMidYMid meet"></svg>
        <div class="panel" id="previewPanel"><h3>关系详情</h3><div class="pmeta">点击左侧任意节点查看</div></div>
      </div>
      <div class="legend" id="previewLegend"></div>
    </section>

    <section class="common-sec">
      <h2>共同观影记录</h2>
      <p class="common-tip">选择两位观影者，查看他们共同出现过的场次（同场同时到场即计入）。输入姓名即时筛选，点击建议项即可选定。</p>
      <div class="common-pick">
        <div class="cv-field">
          <input id="cvA" class="cv-input" placeholder="输入观影者 A" autocomplete="off">
          <div id="cvA_sug" class="cv-sug"></div>
        </div>
        <span class="cv-x">×</span>
        <div class="cv-field">
          <input id="cvB" class="cv-input" placeholder="输入观影者 B" autocomplete="off">
          <div id="cvB_sug" class="cv-sug"></div>
        </div>
        <button class="cv-ok" onclick="runCommon()">查看</button>
      </div>
      <div id="cvResult" class="common-result"></div>
    </section>
  </main>`;
  return wrap(inner, true);
}

/* 关系图（弦图）：在 afterRender 中初始化（innerHTML 注入的 script 不执行，故放此处） */
function initPreviewGraph(){
  const svg=document.getElementById('previewGraph');
  if(!svg) return;
  svg.innerHTML='';            // 每次进入/刷新都重建，确保实时数据
  svg.onwheel=null; svg.onclick=null; svg.onpointerdown=null; svg.onpointermove=null; svg.onpointerup=null; svg.onpointercancel=null; svg.onpointerleave=null;
  const panel0=document.getElementById('previewPanel');
  if(panel0) panel0.innerHTML='<h3>关系详情</h3><div class="pmeta">点击左侧任意节点查看</div>';

  // ---- 计算共看关系 ----
  const MINW=2;                       // 进入统计的边的最低共看次数
  const pair={};
  films.forEach(f=>f.watches.forEach(w=>{
    const ps=[...new Set(w.people.map(canon))];
    for(let i=0;i<ps.length;i++)for(let j=i+1;j<ps.length;j++){
      const a=ps[i],b=ps[j],k=a<b?a+'|'+b:b+'|'+a; pair[k]=(pair[k]||0)+1;
    }
  }));
  // 每位用户：共看总权重（仅计 weight>=MINW）+ 不同搭子数
  const users={};
  Object.entries(pair).forEach(([k,v])=>{
    const [a,b]=k.split('|'); if(v<MINW) return;
    (users[a]=users[a]||{id:a,total:0,partners:new Set()}).total+=v; users[a].partners.add(b);
    (users[b]=users[b]||{id:b,total:0,partners:new Set()}).total+=v; users[b].partners.add(a);
  });
  // 规则：按共看总场次降序，取前 20 位（人数不超过 20）
  const top=Object.values(users).filter(u=>u.total>0)
    .map(u=>({id:u.id,total:u.total,partners:u.partners.size}))
    .sort((x,y)=>y.total-x.total||y.partners-x.partners)
    .slice(0,20);
  const topSet=new Set(top.map(u=>u.id));
  const edgesAll=[];
  Object.entries(pair).forEach(([k,v])=>{
    if(v<MINW) return; const [a,b]=k.split('|');
    if(topSet.has(a)&&topSet.has(b)) edgesAll.push({a,b,w:v});
  });
  if(top.length===0){ const ts=document.getElementById('previewGraphTs'); if(ts) ts.textContent='暂无足够共看数据'; return; }
  const maxW=Math.max(1,...edgesAll.map(e=>e.w));

  // ---- 弦图布局（20 人沿圆周排布，弧形连线粗细=共看次数） ----
  const W=760,H=620,cx=W/2,cy=H/2,R=250;
  const NS='http://www.w3.org/2000/svg';
  let th=3, sel=null;
  const N=top.length;
  const ang=i=>i/N*Math.PI*2-Math.PI/2;
  const pos=i=>({x:cx+Math.cos(ang(i))*R,y:cy+Math.sin(ang(i))*R});
  const nodeEls={}, edgeEls=[];

  function build(){
    const edges=edgesAll.filter(e=>e.w>=th);
    svg.innerHTML=''; edgeEls.length=0;
    for(const k in nodeEls) delete nodeEls[k];
    edges.forEach(e=>{
      const i=top.findIndex(u=>u.id===e.a), j=top.findIndex(u=>u.id===e.b);
      if(i<0||j<0) return; const p1=pos(i),p2=pos(j);
      const path=document.createElementNS(NS,'path');
      path.setAttribute('d','M '+p1.x+' '+p1.y+' Q '+cx+' '+cy+' '+p2.x+' '+p2.y);
      path.setAttribute('class','gedge');
      path.setAttribute('stroke-width',0.8+(e.w/maxW)*7);
      path.setAttribute('stroke-opacity',0.1+(e.w/maxW)*0.5);
      path.__a=e.a; path.__b=e.b; svg.appendChild(path); edgeEls.push(path);
    });
    top.forEach((u,i)=>{
      const p=pos(i), r=6+(u.total/top[0].total)*14;
      const c=document.createElementNS(NS,'circle');
      c.setAttribute('cx',p.x); c.setAttribute('cy',p.y); c.setAttribute('r',r);
      c.setAttribute('class','gnode'); c.__id=u.id; svg.appendChild(c); nodeEls[u.id]=c;
      const t=document.createElementNS(NS,'text');
      t.setAttribute('x',p.x); t.setAttribute('y',p.y-r-4);
      t.setAttribute('text-anchor','middle'); t.setAttribute('class','glabel');
      t.textContent=u.id; svg.appendChild(t);
      c.addEventListener('mouseenter',()=>{ if(!sel) hover(u.id); });
      c.addEventListener('mouseleave',()=>{ if(!sel) clearHL(); });
      c.addEventListener('click',ev=>{ ev.stopPropagation(); select(u.id); });
    });
    if(sel) select(sel);
  }
  function neighbors(id){const m={};edgesAll.forEach(e=>{if(e.w>=th){if(e.a===id)m[e.b]=(m[e.b]||0)+e.w;else if(e.b===id)m[e.a]=(m[e.a]||0)+e.w;}});return m;}
  function hover(id){
    Object.values(nodeEls).forEach(n=>{ if(n.__id!==id) n.classList.add('dim'); else n.classList.add('hot'); });
    svg.querySelectorAll('.glabel').forEach(n=>{ if(n.textContent!==id) n.classList.add('dim'); else n.classList.add('hot'); });
    edgeEls.forEach(l=>{ if(l.__a===id||l.__b===id) l.classList.add('hot'); else l.classList.add('dim'); });
  }
  function clearHL(){ svg.querySelectorAll('.gnode,.glabel,.gedge').forEach(n=>n.classList.remove('dim','hot')); }
  function select(id){
    sel=id; const nb=neighbors(id), nbIds=Object.keys(nb);
    Object.values(nodeEls).forEach(n=>{ if(n.__id!==id&&nbIds.indexOf(n.__id)<0) n.classList.add('dim'); else n.classList.remove('dim'); });
    svg.querySelectorAll('.glabel').forEach(n=>{ if(n.textContent!==id&&nbIds.indexOf(n.textContent)<0) n.classList.add('dim'); else n.classList.remove('dim'); });
    edgeEls.forEach(l=>{ if(l.__a===id||l.__b===id) l.classList.add('hot'); else l.classList.add('dim'); });
    const topP=Object.entries(nb).sort((a,b)=>b[1]-a[1]).slice(0,10);
    const panel=document.getElementById('previewPanel');
    // 去除用户名下方的「共看 xx 人」统计文案，仅展示伙伴清单
    let h='<h3>关系详情</h3><div class="pname">'+id+'</div>';
    topP.forEach(p=>{ h+='<div class="prow"><span>'+p[0]+'</span><span class="cnt">'+p[1]+' 场</span></div>'; });
    panel.innerHTML=h;
  }
  function reset(){ sel=null; clearHL(); const panel=document.getElementById('previewPanel'); if(panel) panel.innerHTML='<h3>关系详情</h3><div class="pmeta">点击左侧任意节点查看</div>'; }
  const slider=document.getElementById('cvTh'), thVal=document.getElementById('cvThVal');
  if(slider){ slider.addEventListener('input',()=>{ th=+slider.value; if(thVal) thVal.textContent=th; build(); }); }
  const rb=document.getElementById('previewReset'); if(rb) rb.onclick=reset;
  svg.onclick=function(e){ if(e.target===svg) reset(); };
  const ts=document.getElementById('previewGraphTs');
  if(ts) ts.textContent='已生成 · '+new Date().toLocaleString('zh-CN');
  const legend=document.getElementById('previewLegend');
  if(legend) legend.innerHTML='规则：按共看总场次降序取前 20 位，沿圆周排布。弧形连线粗细 = 共看次数（≥'+th+'）。悬停/点击高亮其关系。';
  build();
}

/* ---------- 路由 ---------- */
/* ---------- 隐藏页内嵌：共同观影记录（位于弦图模块下方） ----------
   选人改为「输入即时筛选」，避免 112 人下拉过长。 */
function runCommon(){
  const box = document.getElementById('cvResult');
  if(!box) return;
  const a = canon(document.getElementById('cvA').value.trim());
  const b = canon(document.getElementById('cvB').value.trim());
  if(!a || !b){ box.innerHTML = '<div class="empty">请先选择两位观影者</div>'; return; }
  if(a === b){ box.innerHTML = '<div class="empty">两位观影者相同（'+esc(a)+'），请选择不同用户</div>'; return; }
  const rows = [];
  films.forEach(f => f.watches.forEach(w => {
    const cs = w.people.map(p => canon(p));
    if(cs.includes(a) && cs.includes(b)) rows.push({ id:f.id, title:f.title, date:w.date });
  }));
  rows.sort((x,y) => x.date < y.date ? -1 : x.date > y.date ? 1 : 0);
  if(!rows.length){ box.innerHTML = '<div class="empty">'+esc(a)+' 与 '+esc(b)+' 没有共同观影记录</div>'; return; }
  const body = rows.map(r => '<a class="common-row" href="#/film/'+r.id+'">'
      + '<span class="common-date">'+esc(r.date)+'</span>'
      + '<span class="common-film">'+esc(r.title)+'</span></a>').join('');
  box.innerHTML = '<div class="common-count">'+esc(a)+' × '+esc(b)+' 共 '+rows.length+' 次共同观影</div>'+body;
}
function cvSetupPicker(inputId, sugId){
  const inp = document.getElementById(inputId), sug = document.getElementById(sugId);
  if(!inp || !sug) return;
  const names = allWatchers().sort((a,b) => a.localeCompare(b, 'zh'));
  inp.addEventListener('input', () => {
    const q = inp.value.trim().toLowerCase();
    if(!q){ sug.style.display='none'; sug.innerHTML=''; return; }
    const hit = names.filter(n => n.toLowerCase().includes(q)).slice(0, 8);
    if(!hit.length){ sug.style.display='none'; sug.innerHTML=''; return; }
    sug.innerHTML = hit.map(n => '<div class="cv-sug-item" data-n="'+esc(n)+'">'+esc(n)+'</div>').join('');
    sug.style.display = 'block';
    sug.querySelectorAll('.cv-sug-item').forEach(el => {
      el.addEventListener('mousedown', e => {
        e.preventDefault();
        inp.value = el.getAttribute('data-n');
        sug.style.display = 'none'; sug.innerHTML = '';
      });
    });
  });
  inp.addEventListener('blur', () => setTimeout(() => { sug.style.display='none'; sug.innerHTML=''; }, 120));
}
function initCommonView(){
  cvSetupPicker('cvA','cvA_sug');
  cvSetupPicker('cvB','cvB_sug');
}

function render(){
  const p = location.hash || '#/';
  let html;
  if(p === '#/' || p === '#' || p === '') html = home();
  else if(p === '#/cinophile') html = cinephile();
  else if(p === '#/search') html = searchPage();
  else if(p.startsWith('#/film/')) html = filmDetail(p.split('/')[2]);
  else if(p.startsWith('#/director/')) html = directorDetail(p.substring('#/director/'.length));
  else if(p.startsWith('#/day/')) html = dayDetail(p.split('/')[2]);
  else if(p.startsWith('#/person/')) html = personDetail(p.substring('#/person/'.length));
  else if(p === '#/add') html = addWatch();
  else if(p === '#/admin/login') html = adminLogin();
  else if(p === '#/admin/feedback') html = feedbackAdmin();
  else if(p === '#/admin') html = state.admin ? admin() : adminLogin();
  else if(p.startsWith('#/admin/new/')) html = state.admin ? newStep(Number(p.split('/')[3])) : adminLogin();
  else if(p === '#/library') html = library();
  else if(p === '#/preview') html = previewPage();
  else html = wrap(`<div class="empty">页面不存在</div>`, true);
  document.getElementById('app').innerHTML = html;
  window.scrollTo(0,0);
  afterRender(p);
}
/* 渲染后钩子（预留扩展点，现已不依赖海报解析）
   注：通过 innerHTML 注入的 <script> 浏览器不执行，故关系图这类需 JS 初始化的内容放这里。 */
function afterRender(p){
  if(p === '#/preview'){ initPreviewGraph(); initCommonView(); }
}
function go(hash){ location.hash = hash; }

window.addEventListener('hashchange', render);
render();

/* ---------- 隐藏反馈管理页（#/admin/feedback，密码 11999900） ---------- */
function feedbackAdmin(){
  const FB_KEY = 'filmlog_feedback_v1';
  const PW = '11999900';
  const html = `<main class="detail">
    <div class="eyebrow">ADMIN</div>
    <h1 class="entry-title" style="font-size:28px">反馈管理</h1>
    <div class="divider"></div>
    <div id="fbAdmin">
      <div class="fb-login">
        <input id="fbPw" class="fb-pw" type="password" placeholder="输入管理密码" autocomplete="off">
        <button class="fb-ok" onclick="fbUnlock()">进入</button>
        <span id="fbMsg" class="fb-msg"></span>
      </div>
    </div>
    <div class="detail-space"></div>
  </main>`;
  // 延迟绑定：DOM 已渲染后再挂函数（render 后元素存在）
  setTimeout(() => {
    window.fbUnlock = function(){
      const v = document.getElementById('fbPw')?.value || '';
      const msg = document.getElementById('fbMsg');
      if(v !== PW){ if(msg) msg.textContent = '密码错误'; return; }
      let list = [];
      try{ list = JSON.parse(localStorage.getItem(FB_KEY) || '[]'); }catch(e){}
      const body = list.length
        ? list.map((r,i) => `<div class="fb-row"><div class="fb-idx">#${i+1}</div><div class="fb-time">${esc(r.t)}</div><div class="fb-msg">${esc(r.msg)}</div></div>`).join('')
        : `<div class="empty">暂无反馈</div>`;
      const box = document.getElementById('fbAdmin');
      if(box) box.innerHTML = `<div class="fb-count">共 ${list.length} 条反馈</div>${body}`;
    };
    }, 0);
  return wrap(html, true);
}

/* ---------- 用户补充/纠错弹窗（需输入个人代码，写入审核流） ---------- */
function openSuggest(type, target, name){
  const overlay = document.createElement('div');
  overlay.className = 'sg-overlay';
  const isEdit = type === 'edit';
  overlay.innerHTML = `
    <div class="sg-modal">
      <div class="sg-head">${isEdit ? '补充 / 纠错' : '反馈'} · 需验证身份</div>
      <div class="sg-sub">${isEdit ? '补充或更正你的观影记录 / 个人资料（仅参与者名单与个人资料）。稍后生效。' : '你的建议会进入管理员审核。'}</div>
      <label class="sg-label">你的代码（4 位）</label>
      <input id="sgCode" class="sg-input" maxlength="4" placeholder="输入你的 4 位代码" autocomplete="off">
      <label class="sg-label">${isEdit ? '修改内容' : '反馈内容'}</label>
      <textarea id="sgMsg" class="sg-text" placeholder="${isEdit ? '例：8/25《胡丽叶塔》我也在场，请补上我的名字' : '发现信息有误，或有改进建议…'}" maxlength="800"></textarea>
      <div class="sg-status" id="sgStatus"></div>
      <div class="sg-actions">
        <button class="sg-cancel" onclick="this.closest('.sg-overlay').remove()">取消</button>
        <button class="sg-send" onclick="submitSuggest()">提交</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  setTimeout(() => overlay.querySelector('#sgCode').focus(), 0);

  window.submitSuggest = function(){
    const code = overlay.querySelector('#sgCode').value.trim().toUpperCase();
    const msg = overlay.querySelector('#sgMsg').value.trim();
    const status = overlay.querySelector('#sgStatus');
    const who = nameByCode(code);
    if(!who){ status.textContent = '代码无效，请核对你的 4 位代码'; return; }
    if(!msg){ status.textContent = '请填写内容'; return; }
    addSuggest({ type, code, who, target, field: isEdit ? 'watch/people' : 'feedback', before:'', after: msg });
    status.textContent = '已提交，等待管理员审核 ✓';
    overlay.querySelector('#sgMsg').value = '';
    setTimeout(() => overlay.remove(), 1400);
  };
}

/* ---------- 日历新建电影弹窗（凭用户 4 位代码，无需审核） ---------- */
function openCreateFilm(dateStr){
  const overlay = document.createElement('div');
  overlay.className = 'sg-overlay';
  overlay.innerHTML = `
    <div class="sg-modal">
      <div class="sg-head">新建电影 · ${dateStr}</div>
      <div class="sg-sub">输入你的 4 位代码与电影名，将自动生成档案页并挂到该日。无需审核，创建者身份会显示在电影页。未录入观影人员前不给编号。</div>
      <label class="sg-label">你的代码（4 位）</label>
      <input id="cfKey" class="sg-input" maxlength="4" placeholder="输入你的 4 位代码" autocomplete="off">
      <label class="sg-label">电影名</label>
      <input id="cfTitle" class="sg-text" style="min-height:auto;padding:11px 12px;font-family:var(--serif);font-size:15px" placeholder="如 午夜巴黎" maxlength="60">
      <div class="sg-status" id="cfStatus"></div>
      <div class="sg-actions">
        <button class="sg-cancel" onclick="this.closest('.sg-overlay').remove()">取消</button>
        <button class="sg-send" onclick="submitCreateFilm()">创建</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  setTimeout(() => overlay.querySelector('#cfKey').focus(), 0);

  window.submitCreateFilm = function(){
    const code = overlay.querySelector('#cfKey').value.trim().toUpperCase();
    const title = overlay.querySelector('#cfTitle').value.trim();
    const status = overlay.querySelector('#cfStatus');
    const who = nameByCode(code);
    if(!who){ status.textContent = '代码无效，请核对你的 4 位代码'; return; }
    if(!title){ status.textContent = '请填写电影名'; return; }
    const f = createFilm(dateStr, title, who);
    overlay.remove();
    go('#/film/' + f.id);
  };
}

/* ---------- 电影页「添加观影用户」：用户凭 4 位代码把自己加到某场次（免审，直接写） ---------- */
function openAddViewer(filmId){
  const f = films.find(x => x.id == filmId);
  if(!f){ return; }
  const dateOpts = f.watches.map((w,i) =>
    `<option value="${i}">${fmtDate(w.date)}（${w.people.length} 人）</option>`).join('');
  const overlay = document.createElement('div');
  overlay.className = 'sg-overlay';
  overlay.innerHTML = `
    <div class="sg-modal">
      <div class="sg-head">添加观影用户</div>
      <div class="sg-sub">选择场次，输入你的 4 位代码，即可将自己加入该场观影名单。无需审核，立即生效。</div>
      <label class="sg-label">场次</label>
      <select id="avDate" class="sg-text" style="min-height:auto;padding:11px 12px;font-family:var(--serif);font-size:15px">${dateOpts}</select>
      <label class="sg-label">你的代码（4 位）</label>
      <input id="avCode" class="sg-input" maxlength="4" placeholder="输入你的 4 位代码" autocomplete="off">
      <div class="sg-status" id="avStatus"></div>
      <div class="sg-actions">
        <button class="sg-cancel" onclick="this.closest('.sg-overlay').remove()">取消</button>
        <button class="sg-send" onclick="submitAddViewer('${filmId}')">加入</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  setTimeout(() => overlay.querySelector('#avCode').focus(), 0);

  window.submitAddViewer = function(id){
    const f = films.find(x => x.id == id);
    if(!f){ return; }
    const wi = Number(overlay.querySelector('#avDate').value);
    const code = overlay.querySelector('#avCode').value.trim().toUpperCase();
    const status = overlay.querySelector('#avStatus');
    const who = nameByCode(code);
    if(!who){ status.textContent = '代码无效，请核对你的 4 位代码'; return; }
    const w = f.watches[wi];
    if(!w) { status.textContent = '场次不存在'; return; }
    // 姓名归一：trim + 小写 + 别名合并，避免「Chao」/「chao」重复加入同一场
    const key = s => String(s ?? '').trim().toLowerCase();
    const whoKey = key(canon(who));
    const existing = w.people.find(p => key(canon(p)) === whoKey);
    if(existing){ status.textContent = '你已在该场次中'; setTimeout(()=>overlay.remove(),1200); return; }
    w.people.push(who);
    assignFilmNumber(f);          // 首次录入人员后分配正式编号
    save();
    logUserAction({ action:'add_viewer', who, code, film:f.title, filmId:f.id, date:w.date, watchIdx:wi });
    overlay.remove();
    render();
  };
}

/* ---------- 右下角反馈浮层（常驻，独立于路由，写入审核流 SUGGEST_KEY） ---------- */
(function injectFeedback(){
  const wrap = document.createElement('div');
  wrap.className = 'fb-widget';
  wrap.innerHTML = `
    <button class="fb-fab" aria-label="反馈">反馈 <span class="fb-pen">✎</span></button>
    <div class="fb-panel" hidden>
      <div class="fb-head">反馈 · 纠错或建议</div>
      <textarea class="fb-input" placeholder="发现信息有误，或有改进建议，写在这里…" maxlength="800"></textarea>
      <div class="fb-actions">
        <span class="fb-status"></span>
        <button class="fb-cancel">取消</button>
        <button class="fb-send">提交</button>
      </div>
    </div>`;
  document.body.appendChild(wrap);

  const fab = wrap.querySelector('.fb-fab');
  const panel = wrap.querySelector('.fb-panel');
  const input = wrap.querySelector('.fb-input');
  const status = wrap.querySelector('.fb-status');

  function save(msg){
    try{
      addSuggest({ type:'feedback', code:'', who:'匿名', target:'feedback', field:'feedback', before:'', after: msg });
      return true;
    }catch(e){ return false; }
  }
  fab.addEventListener('click', () => {
    panel.hidden = !panel.hidden;
    if(!panel.hidden) input.focus();
  });
  wrap.querySelector('.fb-cancel').addEventListener('click', () => { panel.hidden = true; input.value=''; status.textContent=''; });
  wrap.querySelector('.fb-send').addEventListener('click', () => {
    const msg = input.value.trim();
    if(!msg){ status.textContent = '写点内容再提交吧'; return; }
    if(save(msg)){
      status.textContent = '已收到，谢谢反馈';
      input.value = '';
      setTimeout(() => { panel.hidden = true; status.textContent=''; }, 1400);
    } else {
      status.textContent = '提交失败，请稍后再试';
    }
  });
})();

